window.kbPageData["views/entry/k-07ef47dc10f156ad"] = {"key":"entry/k-07ef47dc10f156ad","state":{"route":"entry/k-07ef47dc10f156ad"},"node":{"id":"k-07ef47dc10f156ad","mode":"k","title":"新质生产力","type":"概念与词义","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#25","政治理论必刷100题#50","江苏 2024 B类 行测#3","江苏 2025 A类 申论#4"],"current":true,"candidates":false,"basisGroup":"","authority":{"text":"辨认这一概念可以看三层。创新在生产中起主导作用，技术突破、要素重新配置和产业升级都可能推动形成新质生产力。衡量其是否形成，核心标志是全要素生产率大幅提升。","location":"2024 年 1 月 31 日中央政治局第十一次集体学习讲话，论述新质生产力内涵的段落","source":"《发展新质生产力是推动高质量发展的内在要求和重要着力点》","url":"https://www.miit.gov.cn/xwdt/szyw/art/2024/art_b5bd362c3f494afa9364887fafca498e.html","checked":"2026-11-24"},"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":4,"reviewDoubt":"新质生产力江苏 2024 B类 行测 · 第 3 题（江苏 2024 B类 行测#3）公开流传的试卷文本与输入所给④措辞一致。尚未查到招录机关发布的原卷、标准答案或命题说明，需核实答案A及命题方是否将④中的“要靠”理解为普遍必要条件。","tags":{"专题":["industry"],"主类":["概念与词义"],"出处性质":["专项题干","专项题解析","机构注释"],"学科":["政治理论","经济"],"来源主题":["产业、科技与对外开放"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"新质生产力是由创新主导，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。","review":{"title":"新质生产力","type":"概念与词义","definition":"新质生产力是由创新主导，具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态。","explanation":"新质生产力由技术革命性突破、生产要素创新性配置和产业深度转型升级催生，以全要素生产率大幅提升为核心标志。科技创新成果应用于产业，可以改造提升传统产业，也可以培育壮大新兴产业、布局建设未来产业。","basis":"据关联原题及所列出处编释。","references":[{"source":"new","location":"新质生产力的基本内涵"},{"source":"web-6d5bb8ed851267ee","location":"2023年9月8日听取黑龙江省委和省政府工作汇报后，关于以科技创新引领产业全面振兴的段落","quote":"整合科技创新资源，引领发展战略性新兴产业和未来产业，加快形成新质生产力。"}],"related":["k-9b15547988c8ddb9","k-0b5dc68bbfc10583"],"examFocus":{"政治理论必刷100题#25":"辨明新质生产力的基本特征及其与新发展理念的关系，分清生产力质态与发展政策目标。","江苏 2024 B类 行测#3":"区分新质生产力的形成动力与产业发展路径，辨别各项表述把二者放在什么位置。","政治理论必刷100题#50":"对照“十五五”谋划部署，辨清总体发展要求、根本价值取向和摆在突出位置的战略任务。","江苏 2025 A类 申论#4":"从文博会、文创项目和青年创业服务中选取事例，论证文化创新经过哪些环节转化为产业发展动能。"}},"aspects":[{"title":"基本内涵与特征","uses":[{"unit":"Q1","role":"直接考查","use":"本题依据2024年1月31日二十届中央政治局第十一次集体学习讲话，判定①所列高科技、高效能、高质量特征及其与新发展理念的关系正确。①与③④合计三项，选C。","evidence":"新质生产力具有高科技、高效能、高质量特征，符合新发展理念的先进生产力质态","qids":["政治理论必刷100题#25"]}]},{"title":"创新驱动与产业转型","uses":[{"unit":"Q3","role":"直接考查","use":"本题以2023年9月黑龙江考察为背景。所给答案A认可生产力跃迁、符合高质量发展要求、以创新驱动为关键三项，排除④。同期讲话在部署传统制造业升级的同时，提出整合科技创新资源、引领发展战略性新兴产业和未来产业。由此可把④的问题理解为将传统产业转型升级这一可行路径表述为普遍必要的路径。此项解释仍待命题方依据确认。","evidence":"③依靠创新驱动是形成新质生产力的关键④形成新质生产力要靠传统产业的转型升级","qids":["江苏 2024 B类 行测#3"]}]},{"title":"“十五五”谋划中的战略位置","uses":[{"unit":"Q2","role":"直接考查","use":"本题是选非题。题据所引2025年4月30日部分省区市“十五五”时期经济社会发展座谈会讲话，要求把因地制宜发展新质生产力摆在更加突出的战略位置。C将这一具体部署表述为推动高质量发展，故选C。D所列传统产业转型升级、发展新兴产业和超前布局未来产业并举，符合该次讲话。","evidence":"“十五五”时期，必须把推动高质量发展摆在更加突出的战略位置","qids":["政治理论必刷100题#50"]}]},{"title":"文化创新赋能","uses":[{"unit":"Q4","role":"解题依据","use":"本题依据给定资料7关于激发全民族文化创新创造活力的指示展开论述。长三角文博会数字体验、苏州文创跨界融合和扬州青年文创服务，可分别说明数字技术催生文化新业态、跨界融合拓展产业空间、版权服务和产学研协作支持持续创新。","evidence":"文化创新赋能新质生产力，文化创造助力奋进新征程","qids":["江苏 2025 A类 申论#4"]}]}],"sources":[{"id":"cd67a12c3d0c8d5b","label":"新质生产力","topic":"产业、科技与对外开放","category":"非时政","text":"1.新质生产力\n新质生产力是创新起主导作用，摆脱传统经济增长方式、生产力发展路径，具有高科技、\n高效能、高质量特征，符合新发展理念的先进生产力质态。\n（1）催生：由技术革命性突破、生产要素创新性配置、产业深度转型升级而催生。\n（2）基本内涵：以劳动者、劳动资料、劳动对象及其优化组合的跃升为基本内涵。\n（3）核心标志：以全要素生产率大幅提升为核心标志。\n（4）关键：关键在质优。\n（5）特点：特点是创新。\n（6）本质：本质是先进生产力。\n（7）显著特点：新质生产力的显著特点是创新，既包括技术和业态模式层面的创新，\n也包括管理和制度层面的创新。\n（8）核心要素：科技创新能够催生新产业、新模式、新动能，是发展新质生产力的核\n心要素。\n（9）本身：新质生产力本身就是绿色生产力。\n（10）基本路径：科技创新和产业创新，是发展新质生产力的基本路径。","source":{"doc":"6cbfb01fe723bba64b75","first":16,"last":16,"page":16,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#25":{"paper":"政治理论必刷100题","n":25,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",7],"asrc":["国省考政治理论必刷100题.pdf",47],"card":"46fbb8f5881a8468bfaa2772","links":[{"id":"k-07ef47dc10f156ad","role":"直接考查","why":"判定该表述需要识别新质生产力由创新主导、具有高科技高效能高质量特征的概念内涵。"}]},"政治理论必刷100题#50":{"paper":"政治理论必刷100题","n":50,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",15],"asrc":["国省考政治理论必刷100题.pdf",63],"card":"248169f283e45fe23ed4f982","links":[{"id":"k-07ef47dc10f156ad","role":"直接考查","why":"讲话明确把因地制宜发展新质生产力摆在“十五五”时期更加突出的战略位置。"}]},"江苏 2024 B类 行测#3":{"paper":"江苏 2024 B类 行测","n":3,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",1],"asrc":["8dd171daee6fc74e9718.pdf",2],"card":"b394a29760ed0577e9e55260","links":[{"id":"k-07ef47dc10f156ad","role":"直接考查","why":"新质生产力是符合高质量发展要求的生产力跃迁，以创新驱动为关键，以现代产业为载体。"}]},"江苏 2025 A类 申论#4":{"paper":"江苏 2025 A类 申论","n":4,"mod":"申论","src":["b1f59532fef09ba66d75.pdf",4],"asrc":["c5e59296c6aaf5bdf3eb.pdf",2],"card":"75ae0c7a64f9e6722b3efb65","links":[{"id":"k-07ef47dc10f156ad","role":"直接考查","why":"创新特征是解释文化创新为何能够赋能新质生产力的概念依据。"}]}},"terms":{"k-9b15547988c8ddb9":{"id":"k-9b15547988c8ddb9","mode":"k","type":"概念与词义","title":"现代化产业体系","qs":[],"count":4},"k-0b5dc68bbfc10583":{"id":"k-0b5dc68bbfc10583","mode":"k","type":"事实与事件","title":"东北振兴中的战略性新兴产业和未来产业","qs":[],"count":3}},"references":{"new":{"name":"习近平：发展新质生产力是推动高质量发展的内在要求和重要着力点","url":"https://www.miit.gov.cn/xwdt/szyw/art/2024/art_b5bd362c3f494afa9364887fafca498e.html"},"web-6d5bb8ed851267ee":{"name":"新华社《习近平在黑龙江考察时强调 牢牢把握在国家发展大局中的战略定位 奋力开创黑龙江高质量发展新局面》","url":"https://www.moe.gov.cn/jyb_xwfb/s6052/moe_838/202309/t20230909_1079208.html"}},"topics":[{"slug":"industry","title":"产业升级与新质生产力"}],"units":{"k-07ef47dc10f156ad":[["政治理论必刷100题#25"],["政治理论必刷100题#50"],["江苏 2024 B类 行测#3"],["江苏 2025 A类 申论#4"]]}};
